const btn=(label,action,kind='',ico='',extra='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const badge=(label,tone='gray')=>`<span class="badge ${tone}">${e(label)}</span>`;
const STEPS=[['cadre','Cadre','folder'],['faits','Faits','pen'],['mesures','Relevés','measure'],['pieces','Pièces','camera'],['contradictoire','Constat','users'],['suivi','Suivi','send']];
const NAV=[['dashboard','Vue d’ensemble','grid'],['documents','Attachements','file'],['projects','Chantiers','folder'],['references','Référentiel','book'],['backup','Sauvegardes','backup'],['settings','Paramètres','settings']];
const S={documents:[],projects:[],settings:C.defaults(),route:'dashboard',step:'cadre',current:null,expectedAt:undefined,dirty:false,editSeq:0,savePromise:null,saveTimer:null,lastRoute:'',filter:'',statusFilter:'all',projectFilter:'all',showArchived:false,refTab:'essentials',refSearch:'',registration:null,offlineReady:false,installPrompt:null,storage:null,modalCleanup:null,uploadTarget:'facts',uploadPurpose:'pv',channel:null,persistenceError:'',navSeq:0};

function toast(message,type=''){const d=document.createElement('div');d.className=`toast ${type}`;d.textContent=message;$('#toast-zone').append(d);setTimeout(()=>d.remove(),type==='error'?12000:5500);}
function busy(button,value=true){if(button){button.disabled=value;button.classList.toggle('loading-button',value);}}
function pageHead(title,description,actions='',eyebrow='Espace de travail'){return `<div class="page-head"><div><div class="eyebrow">${e(eyebrow)}</div><h1>${e(title)}</h1><p>${e(description)}</p></div><div class="actions">${actions}</div></div>`;}
function banner(text,tone='info',title=''){return `<div class="banner ${tone}">${icon(tone==='warn'||tone==='error'?'alert':'info')}<div>${title?`<strong>${title}</strong>`:''}${text}</div></div>`;}
function shell(content){const navRoute=S.route==='editor'?'documents':S.route;const initials=(S.settings.author||'AP').split(/\s+/).map(n=>n[0]).slice(0,2).join('').toUpperCase();const navTitle=NAV.find(x=>x[0]===navRoute)?.[1]||'Attachements';
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar" id="sidebar"><a class="brand" href="#dashboard"><img src="./icons/icon.svg" alt=""><div><strong>Attachement<span style="font-weight:400"> Pro</span></strong><small>Le constat de terrain</small></div></a><div class="nav-label">Votre espace</div><nav class="nav" aria-label="Navigation principale">${NAV.slice(0,3).map(([id,label,ic])=>`<a href="#${id}" class="${navRoute===id?'active':''}" ${navRoute===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='documents'?`<span class="count">${S.documents.length}</span>`:''}</a>`).join('')}<div class="nav-sep"></div>${NAV.slice(3).map(([id,label,ic])=>`<a href="#${id}" class="${navRoute===id?'active':''}" ${navRoute===id?'aria-current="page"':''}>${icon(ic)}${label}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="local-card"><strong><span class="dot"></span> Votre travail reste ici</strong>Dossiers et photos enregistrés sur cet appareil. Pensez aux sauvegardes.</div><a class="side-user" href="#settings"><div class="avatar">${e(initials)}</div><div><strong>${e(S.settings.author||'Votre espace personnel')}</strong><small>${e(S.settings.organization||'Configurer mon profil')}</small></div></a></div></aside><button class="mobile-scrim" data-action="menu-close" aria-label="Fermer le menu"></button><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" aria-label="Ouvrir le menu" data-action="menu">${icon('menu')}</button><span>Attachement Pro</span><span aria-hidden="true">/</span><strong>${e(navTitle)}</strong></div><div class="top-tools"><span class="connection" id="connection">${connectionLabel()}</span>${S.installPrompt?btn('Installer','install','small','download'):''}<span class="date-today">${new Date().toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'})}</span></div></header><div id="update-slot"></div><main id="main" class="main" tabindex="-1">${content}</main></div></div>`;
 renderUpdate();bindDrop();
}
function connectionLabel(){return `<span class="dot ${navigator.onLine?'':'amber'}"></span>${navigator.onLine?(S.offlineReady?'Prêt hors connexion':'En ligne'):'Hors connexion'}`;}
function renderUpdate(){const slot=$('#update-slot');if(!slot)return;slot.innerHTML=S.registration?.waiting?`<div class="banner update-banner">${icon('refresh')}<div>Une nouvelle version est prête.</div><div class="actions">${btn('Mettre à jour','apply-update','small','refresh')}</div></div>`:'';}
const allDeadlines=()=>S.documents.filter(r=>!r.archived).flatMap(r=>C.deadlines(r).map(d=>({...d,record:r}))).sort((a,b)=>a.due.localeCompare(b.due));
function deadlineList(items,limit=5){return items.length?items.slice(0,limit).map(d=>`<a class="deadline" style="display:block" href="#editor/${e(d.record.id)}/suivi"><div class="deadline-title">${e(d.label)}</div><div class="deadline-meta">${e(d.record.meta.title||'Sans objet')} · ${e(C.numberLabel(d.record))}</div><div class="deadline-days ${d.tone}">${d.remaining<0?`Échéance dépassée de ${-d.remaining} j`:d.remaining===0?'Échéance indicative aujourd’hui':`Dans ${d.remaining} j`} · ${C.formatDate(d.due)}</div></a>`).join(''):`<p>Aucune échéance en attente. Les dates de demande, de présentation et de signature alimentent ce suivi.</p>`;}
function docRows(records){return records.map(r=>{const st=C.status(r);return `<a class="doc-row" href="#editor/${e(r.id)}/cadre"><div class="doc-symbol">${icon(r.state==='draft'?'pen':'file')}</div><div><div class="doc-title">${e(r.meta.title||'Attachement sans objet')}</div><div class="doc-meta"><span>${e(C.numberLabel(r))}</span><span>·</span><span>${e(r.meta.operation||r.meta.commandNumber||'Chantier à renseigner')}</span><span>·</span><span>${e(r.meta.enterprise||'Entreprise à renseigner')}</span></div></div><div class="doc-end">${badge(st.label,st.tone)}<small>${C.formatDate(r.updatedAt)}</small></div></a>`;}).join('');}
function emptyDocuments(){return `<div class="empty-state"><div class="empty-illustration" aria-hidden="true"><div class="empty-paper"></div><div class="empty-badge">${icon('plus')}</div></div><h3>Votre premier constat commence ici</h3><p>Consignez les faits, ajoutez vos preuves et préparez un attachement clair, prêt à être présenté.</p>${btn('Créer un attachement','new','primary','plus')}<div><button class="text-btn" data-action="demo">Explorer un exemple fictif ${icon('chevron')}</button></div></div>`;}
function dashboard(){const docs=S.documents.filter(r=>!r.archived),dead=allDeadlines(),drafts=docs.filter(r=>r.state==='draft').length,signed=docs.filter(r=>r.signatures.moe.dataUrl&&r.signatures.enterprise.dataUrl).length;const recent=[...docs].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,6);
 return pageHead('Vos attachements','Du constat sur chantier au dossier prêt à transmettre.',btn('Importer','import-backup','','upload')+btn('Nouvel attachement','new','primary','plus'),'Constats de travaux')+
 `<div class="stats">${[[docs.length,'Attachements','Tous vos dossiers actifs','file',''],[drafts,'En rédaction','Brouillons à compléter','pen','amber'],[signed,'Signés des deux parties','Signatures recueillies','check',''],[dead.length,'Échéances à suivre','Repères de procédure','clock','blue']].map(([n,l,s,i,t])=>`<div class="stat"><div><div class="stat-label">${l}</div><div class="stat-value">${n.toString().padStart(2,'0')}</div><div class="stat-note">${s}</div></div><div class="stat-icon ${t}">${icon(i)}</div></div>`).join('')}</div>`+
 `${S.persistenceError?banner(e(S.persistenceError),'error','Sauvegarde locale indisponible'):''}`+
 `<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Derniers attachements</h2><p>Retrouvez et poursuivez vos constats.</p></div><a class="text-btn" href="#documents">Tout voir ${icon('chevron')}</a></div>${recent.length?`<div class="list-heading"><span>Document et chantier</span><span>État</span></div>${docRows(recent)}`:emptyDocuments()}</section><aside><div class="guide-card"><div class="guide-icon">${icon('book')}</div><div class="eyebrow">Le repère du terrain</div><h3>Des faits précis.<br>Des preuves utiles.</h3><p>Décrivez ce qui a été constaté, relevez les dimensions réelles et légendez vos photos. Le constat précède la disparition des faits.</p><a class="text-btn" href="#references">Consulter les repères ${icon('chevron')}</a><div class="source">RGF00099 · p. 33–35</div></div><div class="right-note"><div class="note-title">${icon('clock')} À garder en vue</div>${deadlineList(dead,3)}<div class="source">Échéances indicatives, procédure à vérifier.</div></div></aside></div><div class="footer-hint">${icon('shield')} Enregistrement local · Aucun compte requis · Exports PDF et Word</div>`;
}
function documentView(){let docs=S.documents.filter(r=>S.showArchived||!r.archived);const q=S.filter.trim().toLowerCase();if(q)docs=docs.filter(r=>[r.meta.title,r.meta.commandNumber,r.meta.operation,r.meta.enterprise,r.number,r.meta.location].join(' ').toLowerCase().includes(q));if(S.statusFilter!=='all')docs=docs.filter(r=>S.statusFilter==='draft'?r.state==='draft':S.statusFilter==='established'?r.state==='established':r.followUp.companyResponse===S.statusFilter);if(S.projectFilter!=='all')docs=docs.filter(r=>r.projectId===S.projectFilter);docs.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));
 return pageHead('Tous les attachements',`${docs.length} dossier${docs.length>1?'s':''} dans cette vue.`,btn('Registre CSV','export-register','','download')+btn('Nouvel attachement','new','primary','plus'))+`<div class="toolbar"><div class="search">${icon('search')}<input id="doc-search" aria-label="Rechercher un attachement" placeholder="Objet, chantier, commande, entreprise…" value="${e(S.filter)}"></div><select id="status-filter" aria-label="Filtrer par état">${[['all','Tous les états'],['draft','Brouillons'],['established','Documents établis'],['reserves','Avec réserves'],['refused','Refus de signer'],['absent','Entreprise absente']].map(([v,l])=>`<option value="${v}" ${v===S.statusFilter?'selected':''}>${l}</option>`).join('')}</select><select id="project-filter" aria-label="Filtrer par chantier"><option value="all">Tous les chantiers</option>${S.projects.map(p=>`<option value="${e(p.id)}" ${p.id===S.projectFilter?'selected':''}>${e(p.name)}</option>`).join('')}</select><label class="check"><input type="checkbox" id="show-archived" ${S.showArchived?'checked':''}>Archives</label></div><section class="panel">${docs.length?docRows(docs):S.documents.length?'<div class="empty-state"><h3>Aucun résultat</h3><p>Essayez un autre mot-clé ou modifiez les filtres.</p></div>':emptyDocuments()}</section>`;
}
function projectsView(){return pageHead('Vos chantiers','Préparez les informations communes et réutilisez-les dans vos constats.',btn('Ajouter un chantier','new-project','primary','plus'))+(S.projects.length?`<div class="grid-cards">${S.projects.map(p=>`<article class="project-card"><div class="project-icon">${icon('folder')}</div><h3>${e(p.name)}</h3><p>${e(p.location||'Emplacement à compléter')}</p><span class="small muted">Commande <strong class="mono">${e(p.commandNumber||'à renseigner')}</strong></span><span class="small muted">${e(p.enterprise||'Entreprise à renseigner')}</span><span class="small muted">${S.documents.filter(r=>r.projectId===p.id).length} attachement(s)</span><div class="tiny-rule"></div><div class="actions">${btn('Créer un constat','new-for-project','small primary','plus',`data-id="${e(p.id)}"`)}${btn('Modifier','edit-project','small','pen',`data-id="${e(p.id)}"`)}</div></article>`).join('')}</div>`:`<section class="panel"><div class="empty-state"><div class="guide-icon" style="margin:0 auto 20px">${icon('folder')}</div><h3>Un cadre commun à vos constats</h3><p>Enregistrez un chantier, son marché et son entreprise pour préparer vos prochains attachements.</p>${btn('Ajouter un chantier','new-project','primary','plus')}</div></section>`);}

function pathValue(object,path){return path.split('.').reduce((o,k)=>o?.[k],object);}
function setPath(object,path,value){const keys=path.split('.');let o=object;for(const k of keys.slice(0,-1))o=o[k];o[keys.at(-1)]=value;}
function field(label,path,{type='text',placeholder='',hint='',full=false,required=false,options=null,large=false,disabled=false,rows=4,value}={}){
 const r=S.current;const v=value??(r?pathValue(r,path):'')??'';const lock=disabled||(r?.state==='established'&&!path.startsWith('followUp.'));const id=`f-${path.replaceAll('.','-')}`;
 const attrs=`id="${id}" data-bind="${e(path)}" ${lock?'disabled':''}`;
 const control=options?`<select ${attrs}>${options.map(x=>{const [val,lab]=Array.isArray(x)?x:[x,x];return `<option value="${e(val)}" ${String(v)===String(val)?'selected':''}>${e(lab)}</option>`;}).join('')}</select>`:type==='textarea'?`<textarea ${attrs} rows="${rows}" class="${large?'large':''}" placeholder="${e(placeholder)}">${e(v)}</textarea>`:`<input ${attrs} type="${type}" value="${e(v)}" placeholder="${e(placeholder)}" ${type==='text'?'autocomplete="off"':''}>`;
 return `<div class="field ${full?'full':''}"><label for="${id}">${e(label)}${required?'<span class="required">*</span>':''}</label>${control}${hint?`<small>${hint}</small>`:''}</div>`;
}
function check(label,path,hint='',disabled=false){const val=pathValue(S.current,path);const lock=disabled||(S.current.state==='established'&&!path.startsWith('followUp.'));return `<div><label class="check"><input type="checkbox" data-bind="${e(path)}" ${val?'checked':''} ${lock?'disabled':''}>${e(label)}</label>${hint?`<p class="small muted" style="margin:7px 0 0 25px">${hint}</p>`:''}</div>`;}
function formTitle(title,subtitle,ico){return `<div class="form-title">${icon(ico)}<div><h2>${title}</h2><p>${subtitle}</p></div></div>`;}
function editorView(){const r=S.current;if(!r)return '';const st=C.status(r),v=C.validateRecord(r,CATEGORIES),stepIndex=STEPS.findIndex(x=>x[0]===S.step),isDraft=r.state==='draft';
 let body={cadre:cadreStep,faits:faitsStep,mesures:measureStep,pieces:evidenceStep,contradictoire:constatStep,suivi:followStep}[S.step]?.()||cadreStep();
 return `<div class="editor-head"><div><a class="text-btn" href="#documents">${icon('back')} Tous les attachements</a><div class="eyebrow">${e(r.meta.commandNumber||'Nouvelle commande')} · ${e(C.numberLabel(r))}${r.documentType!=='initial'?` · ${e(r.documentType)}`:''}</div><h1 class="editor-title">${e(r.meta.title||'Nouvel attachement')}</h1><div class="editor-sub">${badge(st.label,st.tone)}<span class="save-status" id="save-status">${icon('check')} Enregistré sur cet appareil</span></div></div><div class="actions">${btn('Aperçu','preview','','eye')}${btn('Exporter','export-options','','download')}${isDraft?btn('Établir','establish','primary','lock'):btn('Signer','goto-sign','primary','pen')}<details class="more-menu"><summary class="btn icon-btn" aria-label="Autres actions">${icon('more')}</summary><div class="dropdown">${btn('Enregistrer','save','','check')}${btn('Dupliquer en brouillon','duplicate','','copy')}${!isDraft?btn('Créer un rectificatif','rectify','','pen')+btn('Créer un abrogatoire','abrogate','','file'):''}<hr>${btn(r.archived?'Sortir des archives':'Archiver','archive','','archive')}${isDraft?btn('Supprimer le brouillon','delete-document','danger','trash'):''}</div></details></div></div>`+
 `${S.persistenceError?banner(e(S.persistenceError)+' Exportez une sauvegarde avant de fermer cet onglet.','error','Votre dernière saisie n’est pas sauvegardée'):''}${!globalThis.crypto?.subtle?banner('Cet aperçu HTTP permet la rédaction et les exports. Ouvrez la version HTTPS (GitHub Pages) pour établir les constats, recueillir les signatures liées à leur empreinte, chiffrer les sauvegardes et installer la PWA.','info','Adresse HTTPS nécessaire pour les fonctions protégées'):''}`+
 `${!isDraft?banner(`Faits et preuves figés le ${C.formatDateTime(r.lockedAt)}. Les signatures, transmissions et pièces de procédure restent accessibles dans « Suivi ». Toute correction du constat nécessite un nouvel acte.`,'','Attachement établi'):''}`+
 `<nav class="stepper" aria-label="Étapes de rédaction">${STEPS.map(([id,label,ic],i)=>`<a class="step ${id===S.step?'active':''}" href="#editor/${e(r.id)}/${id}" ${id===S.step?'aria-current="step"':''}><strong>${i+1}</strong>${label}${id==='pieces'&&r.evidence.length?` (${r.evidence.length})`:''}</a>`).join('')}</nav><div class="editor-grid"><div><section class="form-panel">${body}</section><div class="form-footer">${stepIndex>0?`<a class="btn" href="#editor/${e(r.id)}/${STEPS[stepIndex-1][0]}">${icon('back')} Précédent</a>`:`<a class="text-btn" href="#documents">Retour aux dossiers</a>`}${stepIndex<5?`<a class="btn primary" href="#editor/${e(r.id)}/${STEPS[stepIndex+1][0]}">Étape suivante ${icon('chevron')}</a>`:isDraft?btn('Vérifier et établir','establish','primary','lock'):btn('Exporter le document','export-options','primary','download')}</div></div><aside><div id="validation-panel">${validationPanel(v)}</div><div class="mini-help"><strong>${icon('book')} Un constat fidèle aux faits</strong>Décrivez les mesures et circonstances observées. Les calculs de règlement et les interprétations restent en dehors de l’attachement.<div class="source">RGF00099 · p. 34–35</div></div>${r.state==='established'?`<div class="audit-box">Empreinte du constat<br><code>${e(r.contentHash.slice(0,24))}…</code><br>Contrôle local d’intégrité. Sans horodatage certifié.</div>`:''}</aside></div>`;
}
function validationPanel(v){return `<div class="progress-card"><h3>Préparation du constat</h3><div class="actions" style="justify-content:space-between"><span class="small muted">Champs essentiels</span><strong class="small">${v.score} %</strong></div><div class="progress-track"><span style="width:${v.score}%"></span></div><p>${v.errors.length?`${v.errors.length} point(s) à compléter avant établissement`:'Les contrôles de saisie sont satisfaits'}</p>${v.errors.slice(0,5).map(x=>`<div class="check-item missing">${icon('circle')}<button data-action="goto-issue" data-step="${x.step}">${e(x.text)}</button></div>`).join('')}${!v.errors.length?`<div class="check-item">${icon('check')} Prêt pour votre vérification humaine.</div>`:''}${v.warnings.length?`<div class="check-item missing">${icon('alert')} ${v.warnings.length} recommandation(s) à relire</div>`:''}${btn('Voir les contrôles','validate','small full','shield')}</div>`;}
function cadreStep(){const r=S.current,m=r.meta;return formTitle('Le cadre de l’attachement','Identifiez le marché, le lieu et l’origine du constat.','folder')+`${r.documentType!=='initial'?banner(`<strong>${r.documentType==='rectificatif'?'Annule et remplace':'Abroge'} le n° ${e(r.relatedNumber)} du ${C.formatDate(r.relatedDate)}.</strong>Un nouveau numéro sera attribué dans la même suite.`,'warn'):''}`+`<div class="form-grid">${field('Chantier / opération','meta.operation',{placeholder:'Ex. Chantier de Montereau',full:true})}${field('Numéro de commande','meta.commandNumber',{required:true,placeholder:'Référence de la commande'})}${field('Entreprise titulaire','meta.enterprise',{required:true,placeholder:'Raison sociale'})}${field('Objet du marché','meta.marketObject',{required:true,full:true,placeholder:'Objet contractuel du marché'})}${field('Emplacement précis des travaux','meta.location',{required:true,full:true,placeholder:'Site, zone, ouvrage, accès…'})}${field('Ligne / section','meta.line',{placeholder:'Ligne, secteur ou bâtiment'})}${field('Voie / équipement','meta.track',{placeholder:'Voie, poste, équipement…'})}${field('PK de début','meta.pkStart',{placeholder:'Ex. 075+320'})}${field('PK de fin','meta.pkEnd',{placeholder:'Ex. 075+380'})}</div><div class="form-section"><h3>Origine du constat</h3><div class="radio-row">${[['moe','À l’initiative de la maîtrise d’œuvre'],['enterprise','À la demande de l’entreprise']].map(([v,l])=>`<label class="radio-card"><input type="radio" name="initiative" data-bind="meta.initiatedBy" value="${v}" ${m.initiatedBy===v?'checked':''} ${r.state!=='draft'?'disabled':''}>${l}</label>`).join('')}</div><div class="form-grid" style="margin-top:18px">${field('Date de l’initiative','meta.initiativeDate',{type:'date'})}${m.initiatedBy==='enterprise'?field('Demande reçue par la MOE le','meta.companyRequestDate',{type:'date',required:true,hint:'Repère de 7 jours pour la constatation (p. 34 et 36).'}):''}${m.initiatedBy==='enterprise'?field('Référence de la demande','meta.companyRequestReference',{full:true,placeholder:'Courriel, courrier, date et auteur…'}):''}</div></div><div class="form-section"><h3>Rédacteur désigné</h3><div class="form-grid">${field('Nom et prénom','meta.author',{required:true})}${field('Fonction','meta.authorRole')}${field('Entité / établissement','meta.authorOrganization',{full:true})}${field('Référence de désignation / habilitation','meta.designationReference',{full:true,placeholder:'Marché, OS ou désignation par la maîtrise d’œuvre'})}</div></div><div class="form-section"><h3>Périmètre de numérotation</h3><p class="record-note">Un numéro continu est attribué lors de l’établissement, à partir de 1 par commande. Les brouillons ne consomment pas de numéro.</p>${check('Commande relevant d’un accord-cadre','meta.framework')}<div class="form-grid" style="margin-top:17px">${m.framework?field('Ordre d’exécution / bon de commande','meta.executionOrder',{required:true})+field('Unité de production','meta.productionUnit',{required:true}):''}</div><div style="margin-top:17px">${check('Numérotation par lot retenue pour ce marché','meta.numberByLot','À utiliser lorsque cette organisation a été proposée et retenue.')}</div>${m.numberByLot?`<div class="form-grid" style="margin-top:17px">${field('Référence du lot','meta.contractLot',{required:true})}</div>`:''}${r.documentType!=='initial'?`<div style="margin-top:20px">${field('Motif de la rectification / abrogation','changeReason',{type:'textarea',required:true,full:true,placeholder:'Expliquer précisément la correction ou l’annulation demandée.'})}</div>`:''}</div>`;}
function faitsStep(){const r=S.current,m=r.meta,cat=CATEGORIES.find(c=>c.id===m.category),prompts=FIELD_PROMPTS[m.category]||[];const groups=[...new Set(CATEGORIES.map(c=>c.group))];
 return formTitle('Les faits constatés','Décrivez les faits et les circonstances, avec précision.','pen')+`<div class="form-grid">${field('Objet de l’attachement','meta.title',{required:true,full:true,placeholder:'Ex. Constat de fouille avant remblaiement'})}<div class="field full"><label for="f-meta-category">Nature du fait / aide à la rédaction</label><select id="f-meta-category" data-bind="meta.category" ${r.state!=='draft'?'disabled':''}><option value="">Autre fait — rédaction libre</option>${groups.map(g=>`<optgroup label="${e(g)}">${CATEGORIES.filter(c=>c.group===g).map(c=>`<option value="${e(c.id)}" ${m.category===c.id?'selected':''}>${e(c.label)}${c.initiative==='B'?' · demande entreprise':c.initiative==='EXCLUDED'?' · autre formalisme':''}</option>`).join('')}</optgroup>`).join('')}</select><small>55 situations issues des tableaux du référentiel fourni.</small></div>${field('Date du fait / début de l’événement','meta.factDate',{type:'date',required:true})}${field('Date de fin, si applicable','meta.factEndDate',{type:'date'})}${field('Heure de début, si utile','meta.factStartTime',{type:'time'})}${field('Heure de fin, si utile','meta.factEndTime',{type:'time'})}</div>`+
 `${cat?`<div style="margin-top:20px">${banner(`${e(cat.hint||'Consigner les faits directement observés.')}${cat.initiative==='B'?'<br>Prévu seulement sur demande du Titulaire.':cat.initiative==='EXCLUDED'?'<br>Un autre formalisme est normalement requis ; tracer l’exigence expresse du Titulaire.':''}<div class="source">RGF00099 · p. ${cat.page}</div>`,['B','EXCLUDED'].includes(cat.initiative)?'warn':'info')}${cat.initiative==='EXCLUDED'?field('Exigence expresse du Titulaire et référence','meta.exceptionRequest',{type:'textarea',required:true}):''}</div>`:''}`+
 `<div class="form-section"><div class="row-head"><h3>Description factuelle</h3>${r.state==='draft'?btn('Insérer une trame','insert-prompts','small','pen'):''}</div>${prompts.length?`<div class="banner"><div><strong>Points utiles pour ce constat</strong>${prompts.map(p=>e(p)).join('<br>')}</div></div>`:''}<div class="form-grid">${field('Ce qui a été constaté','meta.description',{type:'textarea',required:true,full:true,large:true,placeholder:'Ouvrage concerné, nature des travaux, caractéristiques observées, faits datés…'})}${field('Circonstances et conditions d’exécution','meta.conditions',{type:'textarea',full:true,placeholder:'Conditions météo observées, travail de nuit, obstacles, horaires, moyens présents, interruptions…'})}</div><p class="attachment-note">Décrire les faits sans calcul de règlement, conclusion de responsabilité ou qualification de « force majeure ». La saisie ne remplace pas la vérification du rédacteur.</p></div><div class="form-section"><h3>Faits qui ne seront plus vérifiables</h3>${check('Travaux cachés, recouverts ou prochainement inaccessibles','meta.hiddenWorks')}${m.hiddenWorks?`<div class="form-grid" style="margin-top:18px">${field('Disparition / recouvrement prévu le','meta.hiddenBefore',{type:'date',hint:'Rédiger et constater avant cette date.'})}</div>`:''}</div>`;
}
function listField(label,list,id,key,val,{placeholder='',type='text',full=false,options=null,disabled=false}={}){const attrs=`data-list="${list}" data-id="${e(id)}" data-key="${key}" ${disabled?'disabled':''}`;return `<div class="field ${full?'full':''}"><label>${e(label)}${options?`<select ${attrs}>${options.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${e(v)}" ${String(v)===String(val)?'selected':''}>${e(l)}</option>`;}).join('')}</select>`:type==='textarea'?`<textarea ${attrs} placeholder="${e(placeholder)}">${e(val)}</textarea>`:`<input ${attrs} type="${type}" value="${e(val)}" placeholder="${e(placeholder)}">`}</label></div>`;}
function measureStep(){const r=S.current,lock=r.state!=='draft';return formTitle('Quantités et dimensions relevées','Conservez les mesures réelles, sans calcul de règlement.','measure')+banner('Une ligne correspond à un élément constaté. Saisissez une quantité relevée et son unité, puis les dimensions et repères utiles. Aucun total financier ou formule n’est inséré dans l’attachement.','')+`${r.measurements.length?r.measurements.map((q,i)=>`<article class="measure-card"><div class="row-head"><strong>Relevé ${String(i+1).padStart(2,'0')}</strong><div class="actions">${!lock?btn('','move-measure-up','icon-btn small','back',`data-id="${e(q.id)}" aria-label="Monter le relevé" ${i===0?'disabled':''}`)+btn('','remove-measure','icon-btn small danger','trash',`data-id="${e(q.id)}" aria-label="Supprimer le relevé ${i+1}"`):''}</div></div><div class="form-grid">${listField('Désignation de l’élément','measurements',q.id,'designation',q.designation,{full:true,placeholder:'Ex. Fouille du massif M12',disabled:lock})}${listField('Référence du plan / ouvrage','measurements',q.id,'reference',q.reference,{disabled:lock})}${listField('Emplacement / repère','measurements',q.id,'location',q.location,{disabled:lock})}</div><div class="unit-grid">${listField('Quantité relevée','measurements',q.id,'quantity',q.quantity,{placeholder:'Ex. 1 ou 12,50',disabled:lock})}${listField('Unité','measurements',q.id,'unit',q.unit,{placeholder:'u, m, m², m³, h, t…',disabled:lock})}${listField('Dimensions réelles','measurements',q.id,'dimensions',q.dimensions,{placeholder:'L 1,20 m ; l 0,80 m ; prof. 1,10 m',disabled:lock})}</div><div style="margin-top:13px">${listField('Précisions factuelles','measurements',q.id,'note',q.note,{type:'textarea',placeholder:'Nature du terrain, cote, méthode de relevé, instrument…',disabled:lock})}</div></article>`).join(''):`<div class="measure-empty">${icon('measure')}<p>Aucun relevé quantitatif ajouté.</p><p>Ajoutez les quantités ou dimensions utiles au constat.</p></div>`}${!lock?btn('Ajouter un relevé','add-measure','','plus'):''}`;}
function evidenceCard(item,index,procedure=false){const lock=S.current.state!=='draft'&&!procedure,list=procedure?'procedureFiles':'evidence',isPdf=item.mime==='application/pdf';return `<article class="evidence"><button type="button" class="evidence-image" style="width:100%;padding:0;border-left:0;border-right:0;border-top:0;cursor:pointer" data-action="view-evidence" data-id="${e(item.id)}" data-procedure="${procedure}" aria-label="Ouvrir ${e(item.name)}">${isPdf?icon('file'):`<img src="${e(item.dataUrl)}" alt="${e(item.caption||item.name)}" loading="lazy">`}<span class="evidence-num">${procedure?'PROC.':'PIÈCE'} ${String(index+1).padStart(2,'0')}</span></button><div class="evidence-body"><h4>${e(item.name)}</h4><small>${isPdf?'PDF joint séparément':item.type==='sketch'?'Croquis':item.optimized?'Photo — copie optimisée':'Image'} · ${C.formatBytes(item.size||0)}</small>${listField('Légende descriptive',list,item.id,'caption',item.caption,{type:'textarea',placeholder:'Ce que montre la pièce, repère et orientation…',disabled:lock})}${listField('Date du relevé / document',list,item.id,'date',item.date,{type:'date',disabled:lock})}${listField('Localisation / repère',list,item.id,'location',item.location,{placeholder:'PK, ouvrage, orientation…',disabled:lock})}<div class="actions">${btn('Télécharger','download-evidence','small','download',`data-id="${e(item.id)}" data-procedure="${procedure}"`)}${!lock&&!isPdf?btn('Annoter','annotate','small','pen',`data-id="${e(item.id)}" data-procedure="${procedure}"`):''}${!lock?btn('','locate-evidence','small icon-btn','location',`data-id="${e(item.id)}" data-procedure="${procedure}" aria-label="Ajouter ma position"`)+btn('','remove-evidence','small icon-btn danger','trash',`data-id="${e(item.id)}" data-procedure="${procedure}" aria-label="Retirer la pièce"`):''}</div>${!lock&&!procedure&&index>0?`<button class="text-btn" style="font-size:10px;margin-top:12px" data-action="move-evidence-up" data-id="${e(item.id)}">Placer avant la pièce précédente</button>`:''}</div></article>`;}
function evidenceStep(){const r=S.current,lock=r.state!=='draft';return formTitle('Photos, croquis et documents','Légendez chaque pièce pour qu’elle puisse être comprise seule.','camera')+(!lock?`<div class="drop-area" id="drop-area">${icon('upload')}<h3>Ajoutez les preuves du constat</h3><p>Photos JPEG, PNG, WebP et documents PDF · 25 Mo maximum par fichier</p><div class="actions">${btn('Choisir des fichiers','add-evidence','','image')}${btn('Prendre une photo','camera','','camera')}${btn('Dessiner un croquis','sketch','primary','pen')}</div></div>`:banner('Les preuves du constat sont figées. Ajoutez les PV, copies signées et preuves d’envoi dans « Suivi ».','info'))+`<div class="evidence-grid">${r.evidence.map((p,i)=>evidenceCard(p,i)).join('')}</div><p class="attachment-note">Les photos importées sont optimisées pour le téléphone ; conservez vos originaux si nécessaire. Les dates sont à vérifier, elles ne sont pas extraites des données EXIF. Les PDF joints sont listés dans le document et inclus dans le dossier ZIP, sans fusion avec le PDF de l’attachement.</p>`;}
function constatStep(){const r=S.current,lock=r.state!=='draft';return formTitle('La constatation contradictoire','Tracez la convocation et identifiez les personnes présentes.','users')+`<div class="form-grid">${field('Constatation faite le','meta.constatDate',{type:'date',required:true})}${field('Heure du constat, si utile','meta.constatTime',{type:'time'})}${field('Convocation adressée le','meta.invitationDate',{type:'date',required:true})}${field('Moyen de convocation','meta.invitationChannel',{required:true,options:[['','Choisir…'],['Courriel','Courriel'],['Compte rendu de chantier','Compte rendu de chantier'],['Courrier','Courrier'],['Autre moyen tracé','Autre moyen tracé']]})}${field('Référence et preuve de convocation','meta.invitationReference',{type:'textarea',full:true,required:true,placeholder:'Destinataire, date/heure, référence du courriel ou du CR et pièce justificative…'})}</div><div class="form-section"><div class="row-head"><h3>Représentants au constat</h3>${!lock?btn('Ajouter','add-participant','small','plus'):''}</div>${!r.participants.length?`<p class="record-note">Ajoutez les représentants de la maîtrise d’œuvre et de l’entreprise. Leur présence est distincte de l’habilitation des personnes qui signeront.</p>`:r.participants.map((p,i)=>`<article class="participant-card"><div class="row-head"><strong>Représentant ${i+1}</strong>${!lock?btn('','remove-participant','small icon-btn danger','trash',`data-id="${e(p.id)}" aria-label="Retirer le représentant"`):''}</div><div class="form-grid">${listField('Partie représentée','participants',p.id,'party',p.party,{options:[['moe','Maîtrise d’œuvre'],['enterprise','Entreprise titulaire'],['other','Autre intervenant']],disabled:lock})}${listField('Nom et prénom','participants',p.id,'name',p.name,{disabled:lock})}${listField('Entreprise / entité','participants',p.id,'company',p.company,{disabled:lock})}${listField('Fonction','participants',p.id,'role',p.role,{disabled:lock})}${listField('Référence de désignation, si utile','participants',p.id,'habilitation',p.habilitation,{full:true,disabled:lock})}</div><div style="margin-top:15px"><label class="check"><input type="checkbox" data-list="participants" data-id="${e(p.id)}" data-key="present" ${p.present?'checked':''} ${lock?'disabled':''}>Présent lors de la constatation</label></div>${!p.present?`<div style="margin-top:15px">${listField('Circonstances de l’absence','participants',p.id,'absenceReason',p.absenceReason,{type:'textarea',disabled:lock})}</div>`:''}</article>`).join('')}</div><div class="form-section"><h3>Situation de l’entreprise lors de la présentation</h3>${field('Réponse / présence du Titulaire','followUp.companyResponse',{options:[['pending','En attente de présentation / réponse'],['accepted','Acceptation exprimée'],['reserves','Signature avec réserves'],['refused','Refus de signer'],['absent','Absence après convocation']],disabled:!!r.signatures.enterprise.dataUrl})}${r.followUp.companyResponse==='absent'?`<div style="margin-top:17px">${check('J’ai vérifié la convocation et l’absence de représentant de l’entreprise','meta.convocationConfirmed','Les éléments de preuve doivent être conservés. Aucune signature entreprise ne sera créée automatiquement.')}</div>`:''}<p class="record-note" style="margin-top:16px">L’absence, les réserves et le refus se documentent. L’application ne décide pas de l’opposabilité de l’attachement.</p></div>`;}
function signatureCard(party){const r=S.current,s=r.signatures[party],title=party==='moe'?'Maîtrise d’œuvre':'Entreprise titulaire';return `<div class="signature-card"><h3>${title}</h3>${s.name?`<div class="small">${e(s.name)} · ${e(s.role)}</div>`:''}<div class="signature-preview">${s.dataUrl?`<img src="${e(s.dataUrl)}" alt="Signature de ${e(s.name)}">`:'Signature non recueillie'}</div>${s.dataUrl?`<small>Recueillie le ${C.formatDate(s.date)}<br>Habilitation : ${e(s.habilitation)}</small>`:''}${s.dataUrl?btn('Retirer cette signature','remove-signature','small danger','trash',`data-party="${party}"`):btn('Recueillir la signature','sign','small','pen',`data-party="${party}" ${r.state==='draft'||(party==='enterprise'&&['absent','refused'].includes(r.followUp.companyResponse))?'disabled':''}`)}</div>`;}
function followStep(){const r=S.current,f=r.followUp,sgn=!!r.signatures.enterprise.dataUrl,dead=C.deadlines(r);return formTitle('Présentation, signatures et transmission','Gardez la trace des suites données au constat.','send')+`${dead.length?`<div class="banner warn"><div><strong>Échéances indicatives</strong>${dead.map(d=>`${e(d.label)} : ${C.formatDate(d.due)}${d.remaining<0?' · dépassée':''}`).join('<br>')}<div class="source">Vérifiez les modalités de computation et les preuves du marché. Aucun changement automatique d’acceptation.</div></div></div>`:''}`+`<div class="form-grid">${field('Présenté à l’entreprise le','followUp.presentationDate',{type:'date',disabled:sgn})}${field('Situation de l’entreprise','followUp.companyResponse',{options:[['pending','En attente'],['accepted','Acceptation exprimée'],['reserves','Avec réserves'],['refused','Refus de signer'],['absent','Absente après convocation']],disabled:sgn})}${field('Acceptation exprimée le','followUp.acceptanceDate',{type:'date',disabled:sgn})}${field('Notification / réception tracée le','followUp.notifiedDate',{type:'date'})}</div>${['refused','reserves'].includes(f.companyResponse)?`<div class="form-section"><h3>PV de présentation et observations</h3>${banner('Le refus ou les réserves nécessitent un PV de présentation relatant les circonstances, annexé à l’attachement. Le Titulaire dispose d’un repère de 10 jours après présentation pour ses observations écrites (p. 36).','warn')}<div class="form-grid">${field('Référence du PV de présentation','followUp.pvReference')}${field('Date du PV','followUp.pvDate',{type:'date'})}${field('Circonstances de la présentation','followUp.pvCircumstances',{type:'textarea',full:true})}${field(f.companyResponse==='refused'?'Motif / circonstances du refus':'Réserves exprimées','followUp.'+(f.companyResponse==='refused'?'refusalReason':'reservations'),{type:'textarea',full:true,disabled:sgn})}${field('Observations écrites reçues le','followUp.observationsDate',{type:'date'})}${field('Contenu / référence des observations','followUp.observations',{type:'textarea',full:true})}</div>${btn('Préparer le PV de présentation','prepare-pv','','file')}</div>`:''}<div class="form-section"><h3>Représentants habilités et signatures</h3>${r.state==='draft'?banner('Établissez d’abord le constat pour figer les faits et les pièces avant de recueillir les signatures.','info'):''}<div class="signature-grid">${signatureCard('moe')}${signatureCard('enterprise')}</div><p class="attachment-note">Les tracés recueillis à l’écran sont des images de signature liées à l’empreinte locale du constat. Ils ne constituent pas une signature électronique qualifiée ni un horodatage certifié. Vous pouvez aussi joindre un exemplaire signé sur papier.</p></div><div class="form-section"><div class="row-head"><h3>Pièces de procédure</h3>${btn('Ajouter une pièce','add-procedure','small','plus')}</div><p class="record-note">PV, observations, exemplaire signé et justificatifs d’envoi peuvent être ajoutés après établissement. Ils sont distincts des preuves factuelles figées.</p><div class="evidence-grid">${(f.procedureFiles||[]).map((p,i)=>evidenceCard(p,i,true)).join('')}</div></div><div class="form-section"><h3>Transmission et conservation</h3><div class="form-grid">${field('Date de transmission','followUp.dispatchDate',{type:'date',hint:'Pour cet envoi commun. Détaillez les envois séparés dans la référence et les justificatifs.'})}${field('Moyen utilisé','followUp.dispatchMethod',{options:[['','Choisir…'],['Courriel','Courriel'],['Courrier','Courrier'],['Remise contre récépissé','Remise contre récépissé'],['GED / plateforme','GED / plateforme'],['Autre','Autre']]})}${field('Destinataires et coordonnées','followUp.recipients',{type:'textarea',full:true})}${field('Références et preuves de transmission','followUp.dispatchReference',{type:'textarea',full:true,placeholder:'Référence du courriel / récépissé, détail des envois, emplacement du dossier d’exécution et dossier marché…'})}</div><div style="display:grid;gap:12px;margin-top:18px">${check('Original transmis à la maîtrise d’œuvre','followUp.dispatchMoe')}${check('Copie transmise au Titulaire','followUp.dispatchEnterprise')}${check('Copie transmise à l’entité chargée du suivi du marché','followUp.dispatchMarket')}</div><p class="attachment-note">Transmission prévue dans les 7 jours calendaires après signature. Le téléchargement d’un fichier ne vaut pas transmission.</p></div><div class="form-section"><h3>Appréciation de la procédure</h3><div class="form-grid">${field('Vérification / décision humaine documentée','followUp.humanDecision',{type:'textarea',full:true,placeholder:'Vérifications réalisées, pièces examinées et conclusion du responsable, sans qualification automatique par l’application.'})}${field('Responsable de la vérification','followUp.humanDecisionAuthor')}${field('Date de la vérification','followUp.humanDecisionDate',{type:'date'})}</div></div><div class="form-section"><h3>Journal des actions</h3><ol class="timeline">${[...r.journal].reverse().slice(0,35).map(x=>`<li><time>${C.formatDateTime(x.at)}</time>${e(x.text)}</li>`).join('')}</ol><p class="small muted">Journal local. Il facilite le suivi, sans constituer une piste d’audit certifiée.</p></div>`;}

function referencesView(){let cats=CATEGORIES.filter(x=>[x.label,x.group,x.hint,x.initiative].join(' ').toLowerCase().includes(S.refSearch.toLowerCase()));const selected=S.refTab;return pageHead('Les repères de rédaction','Guide intégré à partir des trois documents fournis.','', 'RGF00099 · Version 01 du 03 mars 2026')+`<div class="tabs" role="tablist">${[['essentials','Règles de rédaction'],['categories','Situations et catégories'],['deadlines','Procédure et délais'],['sources','Sources et portée']].map(([v,l])=>`<button class="tab ${selected===v?'active':''}" data-action="ref-tab" data-tab="${v}" role="tab" aria-selected="${selected===v}">${l}</button>`).join('')}</div>`+(selected==='categories'?`<div class="toolbar"><div class="search">${icon('search')}<input id="ref-search" aria-label="Rechercher une situation" placeholder="Intempéries, fouille, voie, document…" value="${e(S.refSearch)}"></div><span class="small muted">${cats.length} situation(s)</span></div><div class="banner"><div>A : prise d’office · B : à la demande du Titulaire · A+B : les deux cas · Autre formalisme : exception sur exigence expresse.</div></div><section class="panel table-wrap"><table class="reference-table"><thead><tr><th>Fait / événement</th><th>Initiative</th><th>Conditions et éléments à relever</th><th>Page</th></tr></thead><tbody>${cats.map(c=>`<tr><td>${e(c.label)}<div class="source">${e(c.group)}</div></td><td>${badge(c.initiative==='EXCLUDED'?'Autre formalisme':c.initiative==='AB'?'A + B':c.initiative,c.initiative==='EXCLUDED'?'red':c.initiative==='B'?'amber':'teal')}</td><td>${e(c.hint||'Description des faits constatés.')}</td><td>${e(c.page)}</td></tr>`).join('')}</tbody></table></section>`:selected==='deadlines'?`<div class="ref-rules"><article class="rule-card"><h3>7 jours · demande de constat</h3><p>Lorsque le Titulaire demande le constat, la constatation doit intervenir dans les sept jours suivant réception de la demande par la maîtrise d’œuvre. La procédure de secours permet l’intervention de la PRM.</p><div class="source">p. 34 et 36</div></article><article class="rule-card"><h3>10 jours · observations écrites</h3><p>En cas de refus ou de réserves, établir un PV de présentation et conserver sa preuve. Le délai court à compter de la présentation des pièces. L’application ne déduit pas automatiquement l’acceptation de l’expiration du délai.</p><div class="source">p. 36</div></article><article class="rule-card"><h3>7 jours calendaires · transmission</h3><p>Après signature, transmettre l’original à la maîtrise d’œuvre et une copie à l’entreprise ainsi qu’à l’entité chargée du suivi du marché. Conserver les pièces dans les dossiers correspondants.</p><div class="source">p. 37</div></article><article class="rule-card"><h3>Avant travaux · représentation</h3><p>Le Titulaire désigne son représentant avant le début des travaux et au plus tard dans les quinze jours suivant la notification du marché. Les signataires désignés par SNCF sont communiqués au Titulaire selon le texte.</p><div class="source">p. 36</div></article></div><div style="margin-top:22px">${banner('Seul le délai de transmission est expressément qualifié de calendaire dans les pièces fournies. Les dates calculées pour les deux autres délais sont des repères : vérifiez leur computation et les conditions du marché.','warn')}</div>`:selected==='sources'?`<section class="form-panel"><h2>Documents utilisés</h2><div class="tiny-rule"></div><p class="record-note">RGF00099, « Exécution des travaux : suivi des marchés », version 01 du 03/03/2026.</p><ul class="small" style="line-height:2.2"><li>Fiche 7 — Les attachements : pages imprimées 33 à 37.</li><li>Annexes — Tableaux 1 et 2 : pages imprimées 38 à 43.</li><li>Modèle fourni « Attachement vierge.docx » : trame d’identification, description et signatures.</li></ul><div class="tiny-rule"></div><p class="record-note">Les sources internes ne sont pas intégrées dans les fichiers destinés à la publication. Le guide synthétise les règles utiles à la rédaction et indique leur pagination. Il ne modifie pas le marché applicable.</p><p class="record-note">Attachement Pro est un outil autonome d’aide à la rédaction, sans certification ni affiliation officielle SNCF. Les contrôles vérifient la saisie ; le responsable vérifie les faits, les habilitations et la procédure.</p></section>`:`<div class="ref-rules">${RULES.map(r=>`<article class="rule-card"><h3>${e(r.title)}</h3><p>${e(r.text)}</p><div class="source">RGF00099 · p. ${e(r.page)}</div></article>`).join('')}</div>`);}
function backupView(){return pageHead('Sauvegardes et transfert','Gardez une copie indépendante de vos attachements et de leurs pièces.')+banner('Les dossiers sont conservés dans le navigateur de cet appareil. Effacer ses données, changer de navigateur, de domaine, de chemin d’installation ou d’appareil ne transfère pas les dossiers. Exportez une sauvegarde avant ces opérations.','warn')+`<div class="backup-grid"><section class="feature-card">${icon('download')}<h2>Exporter tous vos dossiers</h2><p>Une sauvegarde contient les attachements, photos, croquis, pièces de procédure, chantiers et paramètres. Elle permet de reprendre le travail sur un autre appareil.</p><label class="check"><input id="encrypt-backup" type="checkbox">Protéger la sauvegarde par un mot de passe</label><div class="field" style="margin-top:16px"><label for="backup-password">Mot de passe si protection activée</label><input id="backup-password" type="password" autocomplete="new-password" placeholder="10 caractères minimum"><small>Conservez-le : l’application ne peut pas le récupérer.</small></div>${btn('Télécharger la sauvegarde','export-backup','primary','download')}<div class="storage-warning">Dernière préparation de sauvegarde : ${S.settings.lastBackupAt?C.formatDateTime(S.settings.lastBackupAt):'aucun export enregistré'}.<br>Copiez le fichier dans un emplacement de confiance indépendant du téléphone.</div></section><section class="feature-card">${icon('upload')}<h2>Restaurer une sauvegarde</h2><p>Importez un fichier .json ou .attpro. Les dossiers absents de l’appareil sont ajoutés. Les documents déjà présents sont conservés ; les conflits sont signalés.</p>${btn('Choisir une sauvegarde','import-backup','','upload')}<div class="tiny-rule"></div><h3 style="margin-bottom:14px">Sur cet appareil</h3><dl class="kv-list"><dt>Attachements</dt><dd>${S.documents.length}</dd><dt>Chantiers</dt><dd>${S.projects.length}</dd><dt>Images et pièces</dt><dd>${S.documents.reduce((n,r)=>n+r.evidence.length+(r.followUp.procedureFiles?.length||0),0)}</dd><dt>Espace utilisé</dt><dd>${S.storage?C.formatBytes(S.storage.usage||0):'Estimation indisponible'}</dd><dt>Stockage persistant</dt><dd>${S.storage?.persisted?'Accordé':'Non garanti'}</dd></dl><div style="margin-top:20px">${btn('Demander la conservation locale','persist-storage','small','shield')}</div></section></div>`;}
function settingsView(){const fields=[['author','Nom du rédacteur'],['role','Fonction'],['organization','Entité / établissement'],['productionUnit','Unité de production'],['email','Adresse e-mail de référence']];return pageHead('Vos paramètres','Des informations réutilisées dans vos prochains attachements.')+`<div class="backup-grid"><section class="form-panel">${formTitle('Votre profil','Les changements s’appliquent aux futurs documents.','users')}<div class="form-grid">${fields.map(([k,l])=>`<div class="field ${k==='organization'||k==='email'?'full':''}"><label for="setting-${k}">${l}</label><input id="setting-${k}" data-setting="${k}" value="${e(S.settings[k]||'')}" type="${k==='email'?'email':'text'}"></div>`).join('')}</div><div class="form-section"><h3>Qualité des photos intégrées</h3><div class="field"><label for="setting-photo">Taille maximale des copies</label><select id="setting-photo" data-setting="photoQuality"><option value="standard" ${S.settings.photoQuality==='standard'?'selected':''}>Standard · côté long 1 600 px</option><option value="high" ${S.settings.photoQuality==='high'?'selected':''}>Élevée · côté long 2 560 px</option></select><small>Les originaux ne sont pas modifiés. Les photos de l’attachement sont des copies optimisées.</small></div></div><div style="margin-top:22px">${btn('Enregistrer le profil','save-settings','primary','check')}</div></section><section class="feature-card">${icon('download')}<h2>Installer sur cet appareil</h2><p>Sur Android, ouvrez l’adresse HTTPS dans Chrome puis utilisez « Installer l’application » ou le menu du navigateur. Sur iPhone, utilisez le menu de partage et « Sur l’écran d’accueil ».</p>${btn('Installer / afficher l’aide','install','','download')}<div class="tiny-rule"></div><dl class="kv-list"><dt>Version</dt><dd>${C.APP_VERSION}</dd><dt>Programme hors connexion</dt><dd>${S.offlineReady?'Disponible':'À préparer en ligne'}</dd><dt>Compte / serveur métier</dt><dd>Aucun</dd><dt>Synchronisation</dt><dd>Par sauvegarde exportée</dd></dl><div style="margin-top:23px">${btn('Vérifier les mises à jour','check-update','small','refresh')}</div><p class="storage-warning">Après une mise à jour du programme, les dossiers restent dans la base locale. Changez de domaine seulement après une sauvegarde.</p></section></div>`;}

function markDirty(){if(!S.current)return;S.dirty=true;S.editSeq++;clearTimeout(S.saveTimer);S.saveTimer=setTimeout(()=>saveActive().catch(()=>{}),650);updateSaveStatus('Enregistrement…');const panel=$('#validation-panel');if(panel)panel.innerHTML=validationPanel(C.validateRecord(S.current,CATEGORIES));}
function updateSaveStatus(message,error=false){const n=$('#save-status');if(n){n.className=`save-status ${error?'error':''}`;n.innerHTML=icon(error?'alert':'check')+e(message);}}
async function saveActive(){clearTimeout(S.saveTimer);if(S.savePromise){await S.savePromise;if(S.dirty)return saveActive();return;}if(!S.current||!S.dirty)return;const snapshot=C.clone(S.current),seq=S.editSeq,expected=S.expectedAt;snapshot.updatedAt=new Date().toISOString();S.savePromise=DB.put('documents',snapshot,expected).then(()=>{S.expectedAt=snapshot.updatedAt;const i=S.documents.findIndex(x=>x.id===snapshot.id);if(i>=0)S.documents[i]=C.clone(snapshot);else S.documents.push(C.clone(snapshot));if(seq===S.editSeq){S.current.updatedAt=snapshot.updatedAt;S.dirty=false;}S.persistenceError='';updateSaveStatus('Enregistré sur cet appareil');S.channel?.postMessage({type:'saved',id:snapshot.id,updatedAt:snapshot.updatedAt});}).catch(err=>{S.persistenceError=err.name==='QuotaExceededError'?'L’espace de stockage est insuffisant. Exportez votre saisie avant de libérer de l’espace.':err.message;updateSaveStatus('Échec de sauvegarde — exportez votre saisie',true);toast(S.persistenceError,'error');throw err;}).finally(()=>{S.savePromise=null;});await S.savePromise;if(S.current?.id===snapshot.id&&S.dirty)return saveActive();}
async function storeNew(r){await DB.put('documents',r);S.documents.push(C.clone(r));location.hash=`editor/${r.id}/cadre`;}
async function navigate(){if(S.uploadPromise){try{await S.uploadPromise;}catch{return;}}const seq=++S.navSeq;const hash=location.hash.slice(1)||'dashboard';if(hash==='new'){location.hash='dashboard';setTimeout(()=>openNew(),20);return;}try{await saveActive();}catch{if(S.lastRoute){location.hash=S.lastRoute;}return;}if(seq!==S.navSeq)return;const [route,id,step]=hash.split('/');S.route=route;S.current=null;S.expectedAt=undefined;S.dirty=false;S.persistenceError='';if(route==='editor'){const source=await DB.get('documents',id);if(seq!==S.navSeq)return;if(!source){toast('Ce document est introuvable.','error');location.hash='documents';return;}S.current=source;S.current.followUp.procedureFiles||=[];S.expectedAt=source.updatedAt;S.step=STEPS.some(s=>s[0]===step)?step:'cadre';}else if(!NAV.some(n=>n[0]===route)){S.route='dashboard';}S.lastRoute=hash;render();window.scrollTo(0,0);const active=$('.step.active');active?.scrollIntoView({block:'nearest',inline:'nearest'});}
function render(){const renderers={dashboard,documents:documentView,projects:projectsView,references:referencesView,backup:backupView,settings:settingsView,editor:editorView};shell((renderers[S.route]||dashboard)());}
function refreshEditor(){if(S.route==='editor'){const top=window.scrollY;render();window.scrollTo(0,top);}}
function modal(title,body,footer='',wide=false){closeModal();const m=$('#modal');m.className=wide?'wide':'';m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2>${btn('','modal-close','icon-btn ghost','close','aria-label="Fermer"')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;m.showModal();return m;}
function closeModal(){S.modalCleanup?.();S.modalCleanup=null;const m=$('#modal');if(m.open)m.close();}
function askConfirm(title,message,confirm='Confirmer',danger=false){return new Promise(resolve=>{const m=modal(title,`<p>${message}</p>`,btn('Annuler','modal-close')+`<button type="button" id="confirm-yes" class="btn ${danger?'danger':'primary'}">${confirm}</button>`);let done=false;const close=()=>{if(!done){done=true;resolve(false);}m.removeEventListener('close',close);};m.addEventListener('close',close);$('#confirm-yes').onclick=()=>{done=true;resolve(true);closeModal();};});}
async function openNew(projectId=''){await saveActive();const options=S.projects.map(p=>`<option value="${e(p.id)}" ${p.id===projectId?'selected':''}>${e(p.name)}</option>`).join('');modal('Nouvel attachement',`<p>Commencez librement ou reprenez les informations d’un chantier. Le numéro sera attribué lorsque vous établirez le document.</p><div class="form-grid"><div class="field full"><label for="new-project">Chantier</label><select id="new-project"><option value="">Saisie libre — nouveau constat</option>${options}</select></div><div class="field full"><label for="new-title">Objet du constat, si connu</label><input id="new-title" placeholder="Ex. Constat de fouille avant remblaiement"></div></div>`,btn('Annuler','modal-close')+btn('Créer le brouillon','confirm-new','primary','plus'));}
async function openProject(id=''){const p=S.projects.find(x=>x.id===id)||{};const fields=[['name','Nom du chantier'],['commandNumber','Numéro de commande'],['enterprise','Entreprise titulaire'],['marketObject','Objet du marché'],['location','Emplacement'],['line','Ligne / section']];modal(id?'Modifier le chantier':'Ajouter un chantier',`<p>Ces informations seront copiées dans les nouveaux attachements de ce chantier.</p><div class="form-grid">${fields.map(([k,l])=>`<div class="field ${k==='name'||k==='marketObject'?'full':''}"><label for="project-${k}">${l}${k==='name'?' *':''}</label><input id="project-${k}" data-project-field="${k}" value="${e(p[k]||'')}"></div>`).join('')}</div>`,btn('Annuler','modal-close')+btn('Enregistrer le chantier','save-project','primary','check',`data-id="${e(id)}"`));}
function findEvidence(id,procedure){return (procedure?S.current.followUp.procedureFiles:S.current.evidence).find(p=>p.id===id);}
function bindDrop(){const drop=$('#drop-area');if(!drop)return;for(const evt of ['dragenter','dragover'])drop.addEventListener(evt,event=>{event.preventDefault();drop.classList.add('dragover');});drop.addEventListener('dragleave',()=>drop.classList.remove('dragover'));drop.addEventListener('drop',event=>{event.preventDefault();drop.classList.remove('dragover');S.uploadTarget='facts';handleUploads([...event.dataTransfer.files]).catch(err=>toast(err.message,'error'));});}
async function handleUploads(files){
 if(S.uploadPromise){toast('Une importation est déjà en cours.','warn');return;}
 if(!S.current||S.uploadTarget==='facts'&&S.current.state!=='draft')return;
 const r=S.current,kind=S.uploadTarget,purpose=S.uploadPurpose,target=kind==='procedure'?(r.followUp.procedureFiles||=[]):r.evidence;
 const job=async()=>{let count=0;updateSaveStatus('Importation des pièces…');
  for(const f of files){try{if(target.length>=200)throw new Error('Limite de 200 pièces par liste.');const item=await importEvidence(f,S.settings.photoQuality);if(kind==='procedure')item.purpose=purpose;target.push(item);count++;}catch(err){toast(`${f.name} : ${err.message}`,'error');}}
  if(count){C.addEvent(r,'pieces',`${count} pièce(s) ajoutée(s) ${kind==='procedure'?'au suivi de procédure':'au constat'}`);markDirty();await saveActive();refreshEditor();toast(`${count} pièce(s) ajoutée(s). Complétez les légendes et vérifiez les dates.`);}else updateSaveStatus('Enregistré sur cet appareil');
  $('#attachment-input').value='';$('#camera-input').value='';
 };
 S.uploadPromise=job();try{await S.uploadPromise;}finally{S.uploadPromise=null;}
}

async function openDrawing(source=null,procedure=false){if(!S.current)return;if(S.current.state!=='draft'&&!procedure)return;const title=source?'Annoter une copie de la photo':'Dessiner un croquis';const controls=[['pen','Trait libre','pen'],['line','Segment','line'],['arrow','Flèche','arrow'],['rect','Rectangle','rect'],['text','Texte','text']];modal(title,`${source?'<p>L’image d’origine reste conservée. Le dessin produit une nouvelle pièce annotée.</p>':''}<div class="canvas-tools">${controls.map(([t,l,i])=>`<button class="btn small ${t==='pen'?'selected':''}" data-draw-tool="${t}" title="${l}" aria-label="${l}">${icon(i)}<span>${l}</span></button>`).join('')}<label>Couleur <input id="draw-color" type="color" value="#b33b30"></label><label>Trait <select id="draw-width"><option value="3">Fin</option><option value="5" selected>Moyen</option><option value="9">Épais</option></select></label><input id="draw-text" aria-label="Texte à placer sur le croquis" placeholder="Texte à placer…"><button class="btn small icon-btn" id="draw-undo" title="Annuler le dernier trait">${icon('undo')}</button><button class="btn small icon-btn" id="draw-redo" title="Rétablir le trait">${icon('redo')}</button>${!source?'<button class="btn small" id="draw-grid">Quadrillage</button>':''}</div><canvas id="draw-canvas" class="drawing-canvas" aria-label="Zone de dessin au doigt, au stylet ou à la souris"></canvas><div class="field" style="margin-top:18px"><label for="draw-caption">Légende du croquis / de l’annotation</label><textarea id="draw-caption" placeholder="Ouvrage, orientation, cotes, repères et description…">${e(source?.caption||'')}</textarea></div><p class="kbd-note">Choisissez « Texte », saisissez votre légende courte, puis touchez l’endroit où la placer. Ajoutez des cotes explicites ; le croquis n’est pas à l’échelle.</p>`,btn('Annuler','modal-close')+`<button class="btn primary" id="drawing-save">${icon('check')} Ajouter la pièce</button>`,true);
 const board=await drawingBoard($('#draw-canvas'),{background:source?.dataUrl||''});board.setColor('#b33b30');board.setWidth(5);S.modalCleanup=()=>board.destroy();for(const el of $$('[data-draw-tool]'))el.onclick=()=>{board.setTool(el.dataset.drawTool);$$('[data-draw-tool]').forEach(n=>n.classList.toggle('selected',n===el));};$('#draw-color').oninput=ev=>board.setColor(ev.target.value);$('#draw-width').onchange=ev=>board.setWidth(ev.target.value);$('#draw-text').oninput=ev=>board.setText(ev.target.value);$('#draw-undo').onclick=()=>board.undo();$('#draw-redo').onclick=()=>board.redo();if($('#draw-grid'))$('#draw-grid').onclick=()=>board.toggleGrid();
 $('#drawing-save').onclick=async()=>{if(board.isEmpty()){toast('Dessinez au moins un élément avant d’ajouter la pièce.','warn');return;}const caption=$('#draw-caption').value.trim();if(!caption){toast('Ajoutez une légende au croquis.','warn');return;}const dataUrl=board.export();const item={id:C.uid(),type:source?'photo':'sketch',name:`${source?'annotation':'croquis'}-${C.today()}-${C.uid().slice(0,6)}.png`,mime:'image/png',dataUrl,caption,date:C.today(),location:source?.location||'',width:1400,height:900,size:Math.floor(dataUrl.length*.75),...(source?{sourceId:source.id}:{})};if(procedure)item.purpose=source?.purpose||'pv';(procedure?S.current.followUp.procedureFiles:S.current.evidence).push(item);C.addEvent(S.current,'pieces',source?'Ajout d’une copie annotée, original conservé':'Ajout d’un croquis légendé');markDirty();closeModal();await saveActive();refreshEditor();toast('Pièce ajoutée au dossier.');};
}
async function openSignature(party){const r=S.current;if(r.state==='draft'){toast('Établissez d’abord le constat.','warn');return;}if(party==='enterprise'&&['absent','refused'].includes(r.followUp.companyResponse)){toast('Une absence ou un refus ne permet pas de recueillir une signature entreprise.','warn');return;}if(await C.hashContent(r)!==r.contentHash)throw new Error('L’empreinte ne correspond plus au contenu. La signature est bloquée.');if(party==='enterprise'&&!r.followUp.presentationDate){toast('Renseignez la date de présentation avant la signature entreprise.','warn');return;}if(party==='enterprise'&&r.followUp.companyResponse==='reserves'&&!r.followUp.reservations.trim()){toast('Consignez les réserves avant de recueillir la signature.','warn');return;}
 const candidate=r.participants.find(p=>p.party===party&&p.present)||{};modal(`Signature — ${party==='moe'?'maîtrise d’œuvre':'entreprise'}`,`<p>À compléter par le représentant habilité. Le tracé est lié au constat n° ${e(r.number)} établi le ${C.formatDate(r.lockedAt)}.</p><div class="form-grid"><div class="field"><label for="sig-name">Nom et prénom *</label><input id="sig-name" value="${e(candidate.name||'')}"></div><div class="field"><label for="sig-role">Fonction *</label><input id="sig-role" value="${e(candidate.role||'')}"></div><div class="field full"><label for="sig-authority">Référence de l’habilitation / désignation *</label><input id="sig-authority" placeholder="Marché, OS, désignation du représentant…"></div><div class="field"><label for="sig-date">Date de signature *</label><input id="sig-date" type="date" value="${C.today()}"></div></div>${party==='enterprise'?banner(r.followUp.companyResponse==='reserves'?`Signature avec les réserves consignées : ${e(r.followUp.reservations)}`:'La signature entreprise sera enregistrée avec une acceptation exprimée du constat.','info'):''}<div class="row-head" style="margin-top:20px"><strong class="small">Signer dans le cadre</strong><button class="btn small" id="sig-clear">Effacer le tracé</button></div><canvas id="signature-canvas" class="drawing-canvas signature" aria-label="Zone de signature manuscrite"></canvas><label class="check" style="margin-top:18px"><input id="sig-ack" type="checkbox">Je confirme être le signataire nommé, être habilité et avoir pris connaissance du constat et de ses pièces.</label><p class="attachment-note">Image de signature manuscrite, sans certificat ni horodatage qualifié. Si votre procédure impose une autre forme de signature, exportez le document pour la recueillir.</p>`,btn('Annuler','modal-close')+`<button type="button" class="btn primary" id="signature-save">${icon('check')} Enregistrer la signature</button>`,true);
 const board=await drawingBoard($('#signature-canvas'),{signature:true});S.modalCleanup=()=>board.destroy();$('#sig-clear').onclick=()=>board.clear();$('#signature-save').onclick=async()=>{const name=$('#sig-name').value.trim(),role=$('#sig-role').value.trim(),habilitation=$('#sig-authority').value.trim(),date=$('#sig-date').value,ack=$('#sig-ack').checked;if(!name||!role||!habilitation||!date||!ack||board.isEmpty()){toast('Complétez l’identité, la fonction, l’habilitation, la date, le tracé et la confirmation.','warn');return;}if(date<r.lockedAt.slice(0,10)){toast('La signature ne peut pas précéder l’établissement du constat.','warn');return;}r.signatures[party]={name,role,habilitation,date,ack,dataUrl:board.export(),versionHash:r.contentHash};if(party==='enterprise'){if(r.followUp.companyResponse!=='reserves')r.followUp.companyResponse='accepted';if(!r.followUp.acceptanceDate)r.followUp.acceptanceDate=date;}C.addEvent(r,'signature',`Signature ${party==='moe'?'maîtrise d’œuvre':'entreprise'} recueillie : ${name}`);markDirty();closeModal();await saveActive();refreshEditor();toast('Signature enregistrée et liée au constat.');};
}
function showValidation(establish=false){const r=S.current,v=C.validateRecord(r,CATEGORIES);const body=`<p>${establish?'L’établissement attribue le prochain numéro et fige le contenu factuel, les relevés, les personnes présentes et les preuves.':'Ces contrôles aident à compléter le document. Le rédacteur vérifie les faits et la procédure.'}</p>${v.errors.length?`<h3>${v.errors.length} point(s) à compléter</h3><ul class="issue-list errors">${v.errors.map(x=>`<li><a href="#editor/${e(r.id)}/${x.step}" data-action="modal-close-link">${e(x.text)}</a></li>`).join('')}</ul>`:banner('Les champs nécessaires au contrôle de saisie sont renseignés.','', 'Vérification de la saisie réussie')}${v.warnings.length?`<h3>Points à relire</h3><ul class="issue-list">${v.warnings.map(x=>`<li>${e(x.text)}</li>`).join('')}</ul>`:''}${establish&&!v.errors.length?`<p>Numéro prévu dans cette commande : <strong>${C.nextNumber(r,S.documents)}</strong>. La numérotation sera vérifiée au moment de l’enregistrement.</p><label class="check"><input id="establish-ack" type="checkbox">Je confirme avoir vérifié les faits, les pièces, les personnes présentes, le périmètre de numérotation et la procédure applicable.</label><p class="attachment-note">Après établissement, une correction du constat se fera par un nouvel attachement rectificatif ou abrogatoire. Les pièces de procédure restent ajoutables.</p>`:''}`;
 modal(establish?'Vérifier et établir le constat':'Contrôles de rédaction',body,btn('Fermer','modal-close')+(establish&&!v.errors.length?btn('Établir et attribuer le numéro','confirm-establish','primary','lock'):''));
}
async function establishCurrent(){if(!$('#establish-ack')?.checked){toast('Confirmez la vérification du constat avant de l’établir.','warn');return;}await saveActive();const r=S.current;if(r.state!=='draft')return;if(C.validateRecord(r,CATEGORIES).errors.length)throw new Error('Les champs doivent être complétés avant établissement.');const finalize=async()=>{const records=await DB.all('documents');const locked=C.clone(r);locked.number=C.nextNumber(locked,records);locked.scopeNumber=`${C.scopeKey(locked)}#${locked.number}`;locked.state='established';locked.lockedAt=new Date().toISOString();locked.updatedAt=locked.lockedAt;locked.contentHash=await C.hashContent(locked);C.addEvent(locked,'etablissement',`Attachement n° ${locked.number} établi. Faits et preuves figés.`);await DB.put('documents',locked,S.expectedAt);S.current=locked;S.expectedAt=locked.updatedAt;S.dirty=false;const idx=S.documents.findIndex(x=>x.id===r.id);S.documents[idx]=C.clone(locked);S.channel?.postMessage({type:'saved',id:locked.id,updatedAt:locked.updatedAt});};if(navigator.locks)await navigator.locks.request(`attachement-pro-numbering:${DB.APP_SCOPE}`,finalize);else await finalize();closeModal();refreshEditor();toast(`Attachement n° ${S.current.number} établi. Vous pouvez recueillir les signatures.`);}
function exportOptions(){const r=S.current;modal('Exporter l’attachement',`<p>${r.state==='draft'?'Le document portera la mention BROUILLON.':'Le document reprend le constat établi et son suivi actuel.'}</p><div style="display:grid;gap:12px">${btn('PDF — document prêt à transmettre','export-pdf','full primary','file')}${btn('Word — document modifiable (.docx)','export-docx','full','file')}${btn('Dossier complet — PDF, Word, pièces et sauvegarde ZIP','export-zip','full','folder')}${btn('Imprimer / enregistrer avec le navigateur','print','full','print')}${btn('Sauvegarde éditable de cet attachement (.json)','export-record','full','backup')}</div><p class="attachment-note" style="margin-top:18px">Photos et croquis sont intégrés dans PDF et Word. Les PDF annexés sont fournis séparément dans le dossier ZIP. Toute modification externe d’un Word établi doit être gérée selon votre procédure ; la copie figée dans l’application reste inchangée.</p>`,btn('Fermer','modal-close'));}
function readyDownload(blob,filename,label='Télécharger le fichier',note='Retrouvez le fichier dans les téléchargements de votre navigateur, puis conservez-le avec votre dossier de chantier.'){const url=URL.createObjectURL(blob);modal('Votre export est prêt',`<p>Le fichier ${e(filename)} est prêt (${C.formatBytes(blob.size)}). Touchez le bouton ci-dessous pour le télécharger.</p><a class="btn primary full" href="${url}" download="${e(filename)}">${icon('download')} ${e(label)}</a><p class="attachment-note" style="margin-top:18px">${e(note)}</p>`,btn('Fermer','modal-close'));S.modalCleanup=()=>setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function exportAction(format,button){const r=C.clone(S.current);busy(button);try{let blob;if(format==='pdf')blob=await exportPDF(r,S.settings);if(format==='docx')blob=await exportDOCX(r,S.settings);if(format==='zip')blob=await exportDossierZIP(r,S.settings);readyDownload(blob,reportFilename(r,format),`Télécharger le ${format.toUpperCase()}`);}finally{busy(button,false);}}
async function previewRecord(){const r=C.clone(S.current);modal('Aperçu du document',`<p>Préparation de l’aperçu PDF…</p>`,btn('Fermer','modal-close'),true);const blob=await exportPDF(r,S.settings);if(!$('#modal').open)return;const url=URL.createObjectURL(blob);S.modalCleanup=()=>URL.revokeObjectURL(url);$('.modal-body').innerHTML=`<iframe class="report-preview" src="${url}" title="Aperçu PDF de l’attachement"></iframe><p class="attachment-note">Si votre navigateur ne propose pas l’aperçu, utilisez le téléchargement PDF.</p>`;$('.modal-footer').innerHTML=btn('Fermer','modal-close')+btn('Télécharger le PDF','export-pdf','primary','download');}
function printRecord(){const html=buildPrintHTML(C.clone(S.current),S.settings);const frame=document.createElement('iframe');frame.style.cssText='position:fixed;left:-10000px;top:0;width:800px;height:1000px;border:0';frame.title='Version imprimable';frame.srcdoc=html;frame.onload=async()=>{try{await frame.contentDocument.fonts?.ready;await Promise.all([...frame.contentDocument.images].map(img=>img.complete?Promise.resolve():new Promise(res=>{img.onload=res;img.onerror=res;})));frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),120000);}catch(err){frame.remove();toast('L’impression n’est pas disponible ici. Utilisez l’export PDF.','error');}};document.body.append(frame);}
function backupData(single=false){let docs=single?[C.clone(S.current)]:C.clone(S.documents);if(!single&&S.current){const i=docs.findIndex(x=>x.id===S.current.id);if(i>=0)docs[i]=C.clone(S.current);}return {app:'attachement-pro',schemaVersion:1,exportedAt:new Date().toISOString(),documents:docs,projects:single?S.projects.filter(p=>p.id===S.current.projectId):C.clone(S.projects),settings:C.clone(S.settings)};}
async function exportBackup(single=false){let data=backupData(single),encrypted=!single&&$('#encrypt-backup')?.checked;if(encrypted){if(!globalThis.crypto?.subtle)throw new Error('Le chiffrement nécessite la version HTTPS de l’application ou localhost.');data=await C.encryptBackup(data,$('#backup-password').value);}const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),filename=single?reportFilename(S.current,'json'):`attachement-pro-sauvegarde-${C.today()}${encrypted?'.attpro':'.json'}`;if(encrypted)readyDownload(blob,filename,'Télécharger la sauvegarde protégée','Conservez le fichier et son mot de passe dans des emplacements de confiance. Le mot de passe ne peut pas être récupéré.');else downloadBlob(blob,filename);if(!single){S.settings.lastBackupAt=new Date().toISOString();await DB.saveSettings(S.settings);if(S.route==='backup')render();}toast(encrypted?'Sauvegarde protégée prête : utilisez le lien de téléchargement.':'Téléchargement demandé. Vérifiez le fichier et conservez-le hors du navigateur.');}
async function requestPassword(){return new Promise(resolve=>{const m=modal('Sauvegarde protégée','<p>Saisissez le mot de passe utilisé lors de son export.</p><div class="field"><label for="import-password">Mot de passe</label><input id="import-password" type="password" autocomplete="current-password"></div>',btn('Annuler','modal-close')+'<button id="decrypt-import" class="btn primary">Déverrouiller</button>');let done=false;const handler=()=>{if(!done){done=true;resolve(null);}m.removeEventListener('close',handler);};m.addEventListener('close',handler);$('#decrypt-import').onclick=()=>{done=true;resolve($('#import-password').value);closeModal();};});}
async function importBackupFile(file){if(!file)return;if(file.size>180*1024*1024)throw new Error('Sauvegarde supérieure à 180 Mo : séparez les dossiers.');let data;try{data=JSON.parse(await file.text());}catch{throw new Error('Le fichier ne contient pas de JSON valide.');}if(data.app==='attachement-pro-encrypted'){const pw=await requestPassword();if(pw===null)return;data=await C.decryptBackup(data,pw);}C.checkBackup(data);for(const r of data.documents){if(r.state==='established'){if(await C.hashContent(r)!==r.contentHash)throw new Error(`Le contenu de l’attachement n° ${r.number} ne correspond pas à son empreinte. Import refusé.`);for(const s of Object.values(r.signatures))if(s.dataUrl&&s.versionHash!==r.contentHash)throw new Error(`Une signature n’est pas liée à la bonne version du n° ${r.number}.`);r.scopeNumber=`${C.scopeKey(r)}#${r.number}`;}else{r.number=null;delete r.scopeNumber;}r.followUp.procedureFiles||=[];}
 const existing=new Map(S.documents.map(r=>[r.id,r])),newDocs=data.documents.filter(r=>!existing.has(r.id)),conflicts=data.documents.filter(r=>existing.has(r.id)&&JSON.stringify(r)!==JSON.stringify(existing.get(r.id)));const collision=newDocs.find(r=>r.number&&S.documents.some(d=>d.number===r.number&&C.scopeKey(d)===C.scopeKey(r)));if(collision)throw new Error(`Le n° ${collision.number} existe déjà pour cette commande avec un autre identifiant. Aucun document n’a été importé. Réconciliez le registre avant de transférer.`);
 const decision=await new Promise(resolve=>{const m=modal('Vérifier la restauration',`<p><strong>${newDocs.length}</strong> nouveau(x) dossier(s), <strong>${conflicts.length}</strong> dossier(s) déjà présent(s) avec des différences, ${data.projects.length} chantier(s) dans la sauvegarde.</p>${conflicts.length?`<div class="banner warn"><div>Par défaut, vos dossiers locaux sont conservés. Vous pouvez choisir de remplacer les mêmes identifiants par les versions de la sauvegarde après avoir conservé une copie locale.</div></div><label class="check"><input id="import-replace" type="checkbox">Remplacer les ${conflicts.length} dossiers locaux correspondants</label>`:''}<label class="check" style="margin-top:17px"><input id="import-settings" type="checkbox">Reprendre aussi le profil et les paramètres de la sauvegarde</label>`,btn('Annuler','modal-close')+'<button id="import-confirm" class="btn primary">Restaurer la sélection</button>');let done=false;const h=()=>{if(!done){done=true;resolve(null);}m.removeEventListener('close',h);};m.addEventListener('close',h);$('#import-confirm').onclick=()=>{done=true;resolve({replace:!!$('#import-replace')?.checked,settings:!!$('#import-settings')?.checked});closeModal();};});if(!decision)return;
 const selected=[...newDocs,...(decision.replace?conflicts:[])];const candidate=[...S.documents.filter(d=>!selected.some(s=>s.id===d.id)),...selected];C.checkBackup({...data,documents:candidate});if(decision.replace&&conflicts.length){downloadBlob(new Blob([JSON.stringify(backupData(),null,2)],{type:'application/json'}),`attachement-pro-avant-restauration-${C.today()}.json`);}
 const projects=data.projects.filter(p=>!S.projects.some(q=>p.id===q.id));const expectedVersions=Object.fromEntries(selected.map(doc=>[doc.id,existing.get(doc.id)?.updatedAt??null]));await DB.importBatch(selected,projects,decision.settings?{...C.defaults(),...data.settings}:null,expectedVersions);S.documents=await DB.all('documents');S.projects=await DB.all('projects');if(decision.settings)S.settings={...C.defaults(),...await DB.loadSettings()};toast(`${selected.length} dossier(s) restauré(s). ${!decision.replace?conflicts.length:0} version(s) locale(s) conservée(s).`);if(S.route==='editor')location.hash='documents';else render();}
async function storageInfo(){try{const x=await navigator.storage?.estimate();const persisted=await navigator.storage?.persisted?.();S.storage=x?{...x,persisted}:null;}catch{S.storage=null;}}
async function setupPWA(){window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();S.installPrompt=event;if(S.route!=='editor')render();});window.addEventListener('appinstalled',()=>{S.installPrompt=null;toast('Application installée.');});if(!('serviceWorker'in navigator))return;try{S.registration=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});S.offlineReady=!!S.registration.active;renderUpdate();S.registration.addEventListener('updatefound',()=>{const installing=S.registration.installing;installing?.addEventListener('statechange',()=>{if(installing.state==='installed'){S.offlineReady=true;renderUpdate();if($('#connection'))$('#connection').innerHTML=connectionLabel();}});});navigator.serviceWorker.ready.then(()=>{S.offlineReady=true;if($('#connection'))$('#connection').innerHTML=connectionLabel();});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(S.applyingUpdate)location.reload();});if($('#connection'))$('#connection').innerHTML=connectionLabel();}catch(err){S.offlineReady=false;console.warn('Mode hors connexion non prêt',err);}}
async function installApp(){if(S.installPrompt){await S.installPrompt.prompt();await S.installPrompt.userChoice;S.installPrompt=null;return;}modal('Installer Attachement Pro',`<p><strong>Android / Chrome :</strong> ouvrez le site GitHub Pages en HTTPS, puis utilisez le menu ⋮ et « Installer l’application » ou « Ajouter à l’écran d’accueil ».</p><p><strong>iPhone / iPad :</strong> ouvrez l’adresse dans Safari, touchez Partager puis « Sur l’écran d’accueil ».</p><p><strong>Ordinateur :</strong> utilisez l’icône d’installation de Chrome / Edge, si proposée.</p>${banner('Ouvrez une première fois l’application en ligne et attendez « Prêt hors connexion » avant de partir sur chantier. L’installation ne se fait pas depuis un fichier ZIP ou une adresse file://.','info')}<p class="small muted">Si l’installation n’est pas proposée, vérifiez l’HTTPS, la connexion et que vous êtes dans un navigateur complet. Le site reste utilisable sans installation.</p>`,btn('Fermer','modal-close'));}
async function addDemo(){if(!await askConfirm('Explorer un exemple fictif','Créer un dossier d’exemple clairement marqué comme fictif ? Il reste un brouillon, sans numéro de commande réel ni signature.','Créer l’exemple'))return;const r=C.newRecord(S.settings);r.meta={...r.meta,commandNumber:'DEMO-2026-001',enterprise:'Entreprise Exemple — fictive',marketObject:'Exemple de travaux de génie civil',operation:'Chantier de démonstration',location:'Zone fictive, massif M12',line:'Ligne de démonstration',track:'Voie 1',pkStart:'075+320',title:'EXEMPLE FICTIF — Fouille avant remblaiement',description:'Exemple de rédaction à adapter : une fouille rectangulaire est visible au droit du repère M12. Le fond et les parois sont accessibles à l’observation. Les dimensions sont relevées au ruban et au réglet avant recouvrement. Ce dossier est une démonstration ; il ne décrit aucun chantier réel.',conditions:'Exemple : observation de jour, sans eau visible au fond de la fouille.',hiddenWorks:true,hiddenBefore:C.addDays(C.today(),2),category:'dimensions_fouilles'};r.measurements.push({id:C.uid(),designation:'Fouille M12 — exemple fictif',reference:'Plan de démonstration',unit:'u',quantity:'1',dimensions:'L 1,20 m ; l 0,80 m ; profondeur 1,10 m',location:'Repère M12',note:'Dimensions données uniquement pour la démonstration.'});C.addEvent(r,'demonstration','Exemple fictif chargé volontairement');await storeNew(r);}

async function onAction(action,el,event){const r=S.current,id=el?.dataset.id,procedure=el?.dataset.procedure==='true';
 if(S.uploadPromise&&!['menu','menu-close','modal-close'].includes(action)){toast('Patientez pendant l’importation des pièces.','warn');return;}
 switch(action){
 case 'menu':$('#sidebar').classList.toggle('open');return;
 case 'menu-close':$('#sidebar').classList.remove('open');return;
 case 'modal-close':case 'modal-close-link':closeModal();return;
 case 'new':return openNew();
 case 'new-for-project':return openNew(id);
 case 'confirm-new':{const p=S.projects.find(p=>p.id===$('#new-project').value)||{},doc=C.newRecord(S.settings,p);doc.meta.title=$('#new-title').value.trim();closeModal();return storeNew(doc);}
 case 'new-project':return openProject();
 case 'edit-project':return openProject(id);
 case 'save-project':{const p=S.projects.find(p=>p.id===id)||{id:C.uid(),createdAt:new Date().toISOString()};for(const input of $$('[data-project-field]'))p[input.dataset.projectField]=input.value.trim();if(!p.name){toast('Renseignez le nom du chantier.','warn');return;}p.updatedAt=new Date().toISOString();await DB.put('projects',p);S.projects=await DB.all('projects');closeModal();render();toast('Chantier enregistré.');return;}
 case 'save-settings':{for(const input of $$('[data-setting]'))S.settings[input.dataset.setting]=input.value.trim();await DB.saveSettings(S.settings);render();toast('Profil enregistré pour les prochains documents.');return;}
 case 'save':await saveActive();toast('Document enregistré.');return;
 case 'add-measure':r.measurements.push({id:C.uid(),designation:'',reference:'',unit:'',quantity:'',dimensions:'',location:'',note:''});markDirty();refreshEditor();return;
 case 'remove-measure':if(await askConfirm('Retirer le relevé','Retirer cette ligne du brouillon ?','Retirer',true)){r.measurements=r.measurements.filter(q=>q.id!==id);markDirty();refreshEditor();}return;
 case 'move-measure-up':{const i=r.measurements.findIndex(q=>q.id===id);if(i>0)[r.measurements[i-1],r.measurements[i]]=[r.measurements[i],r.measurements[i-1]];markDirty();refreshEditor();return;}
 case 'add-participant':r.participants.push({id:C.uid(),party:r.participants.some(p=>p.party==='moe')?'enterprise':'moe',name:'',company:'',role:'',habilitation:'',present:false,absenceReason:''});markDirty();refreshEditor();return;
 case 'remove-participant':if(await askConfirm('Retirer le représentant','Retirer cette personne de la liste du constat ?','Retirer',true)){r.participants=r.participants.filter(p=>p.id!==id);markDirty();refreshEditor();}return;
 case 'insert-prompts':{if(r.meta.description.trim()&&!await askConfirm('Ajouter une trame','Ajouter les rubriques à la fin de la description existante ?','Ajouter'))return;const prompts=FIELD_PROMPTS[r.meta.category]||['Ouvrage et emplacement','Nature et caractéristiques observées','Date, horaires et circonstances','Références des relevés et pièces'];r.meta.description+=(r.meta.description?'\n\n':'')+prompts.map(p=>`${p}\n[À compléter]`).join('\n\n');markDirty();refreshEditor();return;}
 case 'add-evidence':S.uploadTarget='facts';$('#attachment-input').click();return;
 case 'camera':S.uploadTarget='facts';$('#camera-input').click();return;
 case 'sketch':return openDrawing();
 case 'annotate':return openDrawing(findEvidence(id,procedure),procedure);
 case 'add-procedure':modal('Ajouter une pièce de procédure','<p>Choisissez le type de justificatif, puis son fichier. La pièce restera distincte du constat figé.</p><div class="field"><label for="procedure-purpose">Type de pièce</label><select id="procedure-purpose"><option value="pv">PV de présentation</option><option value="convocation">Preuve de convocation</option><option value="observations">Observations écrites</option><option value="signedCopy">Exemplaire signé</option><option value="dispatch">Preuve de transmission</option></select></div>',btn('Annuler','modal-close')+btn('Choisir le fichier','choose-procedure','primary','upload'));return;
 case 'choose-procedure':S.uploadTarget='procedure';S.uploadPurpose=$('#procedure-purpose').value;closeModal();$('#attachment-input').click();return;
 case 'view-evidence':{const item=findEvidence(id,procedure);if(item.mime==='application/pdf'){downloadBlob(dataURLBlob(item.dataUrl),item.name);return;}modal('Pièce du dossier',`<img class="photo-full" src="${e(item.dataUrl)}" alt="${e(item.caption)}"><p style="margin-top:18px">${e(item.caption||'Légende à compléter')}</p><p class="small muted">${C.formatDate(item.date)} · ${e(item.location)}</p>`,btn('Fermer','modal-close'),true);return;}
 case 'download-evidence':{const item=findEvidence(id,procedure);downloadBlob(dataURLBlob(item.dataUrl),item.name);return;}
 case 'remove-evidence':if(await askConfirm('Retirer la pièce','Retirer cette pièce du dossier sur cet appareil ?','Retirer',true)){if(procedure)r.followUp.procedureFiles=r.followUp.procedureFiles.filter(p=>p.id!==id);else r.evidence=r.evidence.filter(p=>p.id!==id);C.addEvent(r,'pieces','Retrait d’une pièce '+(procedure?'de procédure':'du brouillon'));markDirty();refreshEditor();}return;
 case 'move-evidence-up':{const i=r.evidence.findIndex(p=>p.id===id);if(i>0)[r.evidence[i-1],r.evidence[i]]=[r.evidence[i],r.evidence[i-1]];markDirty();refreshEditor();return;}
 case 'locate-evidence':{if(!navigator.geolocation)throw new Error('La géolocalisation n’est pas disponible.');busy(el);navigator.geolocation.getCurrentPosition(pos=>{const item=findEvidence(id,procedure);if(item){item.location=`${pos.coords.latitude.toFixed(6)}, ${pos.coords.longitude.toFixed(6)} (précision annoncée ±${Math.round(pos.coords.accuracy)} m)${item.location?' · '+item.location:''}`;markDirty();refreshEditor();toast('Position ajoutée. Vérifiez son lien avec la pièce.');}busy(el,false);},err=>{busy(el,false);toast(err.code===1?'Localisation non autorisée. Saisissez le repère manuellement.':'Position indisponible. Saisissez le repère manuellement.','warn');},{enableHighAccuracy:true,timeout:15000,maximumAge:0});return;}
 case 'validate':showValidation();return;
 case 'goto-issue':location.hash=`editor/${r.id}/${el.dataset.step}`;return;
 case 'establish':await saveActive();showValidation(true);return;
 case 'confirm-establish':busy(el);try{await establishCurrent();}finally{busy(el,false);}return;
 case 'goto-sign':location.hash=`editor/${r.id}/suivi`;return;
 case 'sign':return openSignature(el.dataset.party);
 case 'remove-signature':if(await askConfirm('Retirer la signature','Retirer ce tracé du suivi ? L’action sera consignée. Conservez les versions déjà transmises.','Retirer',true)){const party=el.dataset.party;C.addEvent(r,'signature',`Signature ${party==='moe'?'maîtrise d’œuvre':'entreprise'} retirée du suivi local`);r.signatures[party]=C.blankSignature();markDirty();await saveActive();refreshEditor();}return;
 case 'duplicate':await saveActive();return storeNew(C.duplicateRecord(r,S.settings));
 case 'rectify':case 'abrogate':{await saveActive();const kind=action==='rectify'?'rectificatif':'abrogatoire';if(await askConfirm(`Créer un ${kind}`,`Un nouveau brouillon sera lié au n° ${e(r.number)}. L’original restera conservé et le prochain numéro sera attribué lors de l’établissement du nouvel acte.`,`Créer le ${kind}`))return storeNew(C.makeCorrection(r,kind,S.settings));return;}
 case 'archive':if(await askConfirm(r.archived?'Sortir des archives':'Archiver ce dossier',r.archived?'Le dossier reviendra dans les vues actives.':'Le dossier sera masqué des vues actives, sans suppression. Sa numérotation sera conservée.',r.archived?'Restaurer':'Archiver')){r.archived=!r.archived;C.addEvent(r,'archive',r.archived?'Dossier archivé':'Dossier sorti des archives');markDirty();await saveActive();location.hash='documents';}return;
 case 'delete-document':if(r.state!=='draft')return;if(await askConfirm('Supprimer le brouillon','Cette suppression retire le brouillon et ses pièces de cet appareil. Exportez-le si vous souhaitez le conserver.','Supprimer',true)){clearTimeout(S.saveTimer);await saveActive();await DB.remove('documents',r.id);S.documents=S.documents.filter(d=>d.id!==r.id);S.current=null;S.dirty=false;location.hash='documents';toast('Brouillon supprimé.');}return;
 case 'export-options':exportOptions();return;
 case 'export-pdf':return exportAction('pdf',el);
 case 'export-docx':return exportAction('docx',el);
 case 'export-zip':return exportAction('zip',el);
 case 'export-record':return exportBackup(true);
 case 'preview':busy(el);try{await previewRecord();}finally{busy(el,false);}return;
 case 'print':printRecord();return;
 case 'export-register':downloadBlob(exportCSV(S.documents),`registre-attachements-${C.today()}.csv`);toast('Registre CSV téléchargé.');return;
 case 'export-backup':busy(el);try{await exportBackup();}finally{busy(el,false);}return;
 case 'import-backup':await saveActive();$('#backup-input').click();return;
 case 'ref-tab':S.refTab=el.dataset.tab;render();return;
 case 'persist-storage':{const ok=await navigator.storage?.persist?.();await storageInfo();render();toast(ok?'Conservation locale accordée. Continuez à exporter des sauvegardes.':'Le navigateur ne garantit pas la conservation. Exportez régulièrement vos dossiers.',ok?'':'warn');return;}
 case 'install':return installApp();
 case 'check-update':if(!S.registration){toast('Le service hors connexion n’est pas encore prêt. Ouvrez l’application en HTTPS.','warn');return;}await S.registration.update();renderUpdate();toast(S.registration.waiting?'Une nouvelle version est prête.':'Vérification des mises à jour terminée.');return;
 case 'apply-update':await saveActive();if(await askConfirm('Installer la mise à jour','Votre saisie est enregistrée. Recharger maintenant avec la nouvelle version du programme ?','Mettre à jour')){S.applyingUpdate=true;S.registration.waiting?.postMessage({type:'SKIP_WAITING'});}return;
 case 'demo':return addDemo();
 case 'prepare-pv':modal('Préparer le PV de présentation',`<p>Le projet reprend les informations saisies : attachement, date de présentation, personnes et circonstances, refus ou réserves. Complétez ces champs dans « Suivi » avant l’export.</p><p>Le PDF produit est un <strong>projet de PV</strong>, avec des emplacements de signature propres. Recueillez les signatures selon votre procédure puis joignez l’exemplaire final comme pièce de procédure.</p>`,btn('Fermer','modal-close')+btn('Télécharger le projet de PV','export-pv','primary','download'));return;
 case 'export-pv':busy(el);try{const blob=await exportPresentationPV(r,S.settings);readyDownload(blob,`projet-pv-presentation-${r.number||'brouillon'}-${C.today()}.pdf`,'Télécharger le projet de PV','Ce projet de PV doit être vérifié, complété et signé selon votre procédure avant d’être joint au dossier.');}finally{busy(el,false);}return;
 }
}

document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(el.tagName!=='A'||action!=='modal-close-link')event.preventDefault();Promise.resolve(onAction(action,el,event)).catch(err=>{console.error(err);toast(err.message||'L’opération n’a pas abouti. Vos dossiers restent conservés.','error');});});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='doc-search'){S.filter=el.value;const start=el.selectionStart;render();const field=$('#doc-search');field.focus();field.setSelectionRange(start,start);return;}if(el.id==='ref-search'){S.refSearch=el.value;const start=el.selectionStart;render();const field=$('#ref-search');field.focus();field.setSelectionRange(start,start);return;}if(!S.current)return;if(el.dataset.bind){const path=el.dataset.bind;if(S.current.state!=='draft'&&!path.startsWith('followUp.'))return;if(el.type==='radio'&&!el.checked)return;const value=el.type==='checkbox'?el.checked:el.value;if(path==='followUp.companyResponse'&&value==='absent'&&S.current.state==='established'&&S.current.participants.some(p=>p.party==='enterprise'&&p.present)){el.value=S.current.followUp.companyResponse;toast('Le constat établi comporte un représentant entreprise présent. Une correction de ce fait nécessite un rectificatif.','warn');return;}setPath(S.current,path,value);markDirty();}else if(el.dataset.list){const list=el.dataset.list;if(S.current.state!=='draft'&&list!=='procedureFiles')return;const target=(list==='procedureFiles'?S.current.followUp.procedureFiles:S.current[list])?.find(x=>x.id===el.dataset.id);if(target){target[el.dataset.key]=el.type==='checkbox'?el.checked:el.value;markDirty();}}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='status-filter'){S.statusFilter=el.value;render();return;}if(el.id==='project-filter'){S.projectFilter=el.value;render();return;}if(el.id==='show-archived'){S.showArchived=el.checked;render();return;}if(!S.current)return;if(el.dataset.bind&&['meta.initiatedBy','meta.framework','meta.numberByLot','meta.hiddenWorks','meta.category','followUp.companyResponse'].includes(el.dataset.bind)){if(el.dataset.bind.startsWith('followUp.'))C.addEvent(S.current,'suivi',`Situation entreprise renseignée : ${el.options?.[el.selectedIndex]?.text||el.value}`);refreshEditor();}if(el.dataset.list==='participants'&&el.dataset.key==='present')refreshEditor();});
$('#attachment-input').addEventListener('change',event=>handleUploads([...event.target.files]).catch(err=>toast(err.message,'error')));
$('#camera-input').addEventListener('change',event=>handleUploads([...event.target.files]).catch(err=>toast(err.message,'error')));
$('#backup-input').addEventListener('change',async event=>{try{await importBackupFile(event.target.files[0]);}catch(err){console.error(err);toast(err.message,'error');}finally{event.target.value='';}});
$('#modal').addEventListener('cancel',()=>{S.modalCleanup?.();S.modalCleanup=null;});
window.addEventListener('hashchange',()=>navigate().catch(err=>toast(err.message,'error')));
window.addEventListener('beforeunload',event=>{if(S.dirty||S.savePromise||S.uploadPromise){event.preventDefault();event.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveActive().catch(()=>{});});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();saveActive().then(()=>toast('Saisie enregistrée.')).catch(()=>{});}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();$('#doc-search')?.focus();}});
for(const evt of ['online','offline'])window.addEventListener(evt,()=>{const label=$('#connection');if(label)label.innerHTML=connectionLabel();});

async function boot(){try{await DB.openDB();[S.documents,S.projects,S.settings]=await Promise.all([DB.all('documents'),DB.all('projects'),DB.loadSettings().then(x=>({...C.defaults(),...x}))]);await storageInfo();if('BroadcastChannel'in window){S.channel=new BroadcastChannel(`attachement-pro-documents:${DB.APP_SCOPE}`);S.channel.onmessage=async event=>{if(event.data?.type==='saved'){if(S.current?.id===event.data.id){if(event.data.updatedAt!==S.expectedAt)toast('Ce dossier a changé dans un autre onglet. Rouvrez-le avant de poursuivre.','warn');}else{S.documents=await DB.all('documents');if(S.route!=='editor')render();}}};}await navigate();setupPWA();}catch(err){console.error(err);$('#app').innerHTML=`<div class="error-fatal"><h1>Ouverture impossible</h1><p style="margin-top:20px">${e(err.message)}</p><p style="margin-top:15px">Ouvrez l’application en HTTPS dans un navigateur autorisant le stockage local. Vos données existantes n’ont pas été supprimées.</p><button class="btn primary" id="reload-app" style="margin-top:20px">Réessayer</button></div>`;$('#reload-app').onclick=()=>location.reload();}}
boot();
